<h1><?= te('Your Gmail inbox') ?></h1><p class="sub"><?= te('Your connected mailbox stays private to your account. Read and send messages here; reconnect Google to grant sending permission.') ?></p><?php if(!$configured): ?><div class="card"><h2><?= te('Google setup required') ?></h2><p><?= te('Configure the Google Cloud OAuth client, callback URL, Gmail API and encryption key on the server. Each user then authorizes their own account.') ?></p></div><?php elseif(!$connection): ?><a class="btn" href="/google-start"><?= te('Connect my Gmail account') ?></a><?php else: ?><div class="card row"><span><?= e($connection['email']) ?></span><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="disconnect"><button class="btn ghost"><?= te('Disconnect local access') ?></button></form></div><form class="card row" method="get"><input name="q" value="<?= e($_GET['q'] ?? 'in:inbox') ?>" placeholder="<?= te('Search Gmail') ?>"><button class="btn"><?= te('Refresh / search') ?></button></form><?php endif; ?><?php if($error): ?><div class="flash err"><?= e($error) ?></div><?php endif; ?><div class="grid g2"><div class="card"><?php foreach($messages as $m): ?><article><a href="/inbox?message_id=<?= e($m['id']) ?>"><b><?= e($m['subject']) ?></b></a><p class="small muted"><?= e($m['from'].' · '.$m['date']) ?></p><p><?= e($m['snippet']) ?></p></article><?php endforeach; ?></div><?php if($selected!==null): ?><div class="card" style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e($selected) ?></div><?php endif; ?></div>
<?php if($configured&&$connection): ?><div class="card"><h2><?= te('Compose email') ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="send"><label><?= te('Recipient') ?><input name="recipient" type="email" required maxlength="190"></label><label><?= te('Subject') ?><input name="subject" required maxlength="190"></label><label><?= te('Message') ?><textarea name="body" required maxlength="20000" rows="8"></textarea></label><button class="btn"><?= te('Send email') ?></button></form><p><a href="/google-start"><?= te('Reconnect Google for sending permission') ?></a></p></div><?php endif; ?>
